client.batches.create({
  requests: docs.map((doc, i) => ({
    custom_id: `debt-report-${i}`,
    params: { model, max_tokens, messages: [{ role: "user", content: doc }] }
  }))
});

// Anti-pattern: ask the SAME session to review its own code
// Correct: a fresh instance with only the code to review
client.messages.create({ messages: [{ role: "user",
  content: `Review this code for bugs, security, edge cases:\n${code}` }] });
